import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused operation
cpp_source = """
torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor weight_col_sum, float bias_sum);
"""

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_kernel(const float* x, const float* weight_col_sum, float bias_sum, float* out, int batch_size, int in_features) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int block_dim = blockDim.x;

    float sum = 0.0f;
    for (int i = tid; i < in_features; i += block_dim) {
        sum += x[row * in_features + i] * weight_col_sum[i];
    }
    sdata[tid] = sum;
    __syncthreads();

    for (int s = block_dim / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[row] = sdata[0] + bias_sum;
    }
}

torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor weight_col_sum, float bias_sum) {
    const auto batch_size = x.size(0);
    const auto in_features = x.size(1);
    auto out = torch::empty({batch_size, 1}, x.options());

    const int block_size = 256;
    const int num_blocks = batch_size;
    const int shared_mem_size = block_size * sizeof(float);

    fused_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(), weight_col_sum.data_ptr<float>(), bias_sum,
        out.data_ptr<float>(), batch_size, in_features);

    return out;
}
"""

fused_op = load_inline(
    name="fused_op",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_op_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        self.bias = nn.Parameter(torch.empty(out_features))
        self.reset_parameters()
        # Precompute reductions for the fused operation
        weight_col_sum = self.weight.sum(dim=0)
        bias_sum = self.bias.sum()
        self.register_buffer('weight_col_sum', weight_col_sum)
        self.register_buffer('bias_sum', bias_sum)
        self.fused_op = fused_op

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return self.fused_op.fused_op_cuda(x, self.weight_col_sum, self.bias_sum.item())

