import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel with warp shuffle reduction and float4 vectorized loads
fused_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_kernel_v2(
    const float* __restrict__ x,
    const float* __restrict__ weight_col_sum,
    const float bias_sum,
    float* __restrict__ out,
    int batch_size,
    int in_features)
{
    int row = blockIdx.x;
    if (row >= batch_size) return;

    __shared__ float warp_sums[8]; // 256 threads -> 8 warps
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;

    int n4 = in_features / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x + row * in_features);
    const float4* w4 = reinterpret_cast<const float4*>(weight_col_sum);

    float sum = 0.0f;
    for (int i = threadIdx.x; i < n4; i += blockDim.x) {
        float4 xv = x4[i];
        float4 wv = w4[i];
        sum += xv.x * wv.x + xv.y * wv.y + xv.z * wv.z + xv.w * wv.w;
    }

    // Warp-level reduction using shuffle
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_xor_sync(0xffffffff, sum, offset);
    }

    if (lane_id == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    // Reduce warp sums within the first warp
    if (warp_id == 0) {
        float val = (lane_id < 8) ? warp_sums[lane_id] : 0.0f;
        for (int offset = 4; offset > 0; offset >>= 1) {
            val += __shfl_xor_sync(0xffffffff, val, offset);
        }
        if (lane_id == 0) {
            out[row] = val + bias_sum;
        }
    }
}

